// --- STUDIO EDITOR COMPONENT (V2 - AI TOOLS INTEGRATED) ---
const StudioEditor = ({ task, baseImageBase64, onClose, showToast }) => {
    const [bgImage, setBgImage] = useState(baseImageBase64);
    const [studioMode, setStudioMode] = useState('move'); // 'move' | 'erase'
    const [brushSize, setBrushSize] = useState(40);
    const [isProcessing, setIsProcessing] = useState(false);
    const [hasMask, setHasMask] = useState(false);
    
    const canvasRef = useRef(null);
    const isDrawing = useRef(false);

    // Set resolusi asli canvas sesuai gambar
    useEffect(() => {
        const img = new Image();
        img.onload = () => {
            if (canvasRef.current) {
                canvasRef.current.width = img.width;
                canvasRef.current.height = img.height;
            }
        };
        img.src = bgImage;
    }, [bgImage]);

    // Canvas Drawing Logic (Magic Eraser)
    const getPos = (e) => {
        const rect = canvasRef.current.getBoundingClientRect();
        const scaleX = canvasRef.current.width / rect.width;
        const scaleY = canvasRef.current.height / rect.height;
        return {
            x: (e.clientX - rect.left) * scaleX,
            y: (e.clientY - rect.top) * scaleY
        };
    };

    const startDrawing = (e) => {
        if (studioMode !== 'erase') return;
        isDrawing.current = true;
        const pos = getPos(e);
        const ctx = canvasRef.current.getContext('2d');
        ctx.beginPath();
        ctx.moveTo(pos.x, pos.y);
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.strokeStyle = 'rgba(236, 72, 153, 0.6)'; // Pink transparent
        ctx.lineWidth = brushSize;
    };

    const draw = (e) => {
        if (!isDrawing.current || studioMode !== 'erase') return;
        const pos = getPos(e);
        const ctx = canvasRef.current.getContext('2d');
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
        setHasMask(true);
    };

    const stopDrawing = () => {
        if (isDrawing.current) {
            const ctx = canvasRef.current.getContext('2d');
            ctx.closePath();
            isDrawing.current = false;
        }
    };

    // Client-Side Remove Background Logic (White/Solid Color Removal)
    const handleRemoveBG = async () => {
        setIsProcessing(true);
        if (showToast) showToast("Menganalisa dan menghapus latar belakang...", "info");
        
        // Simulasi delay proses AI
        await new Promise(r => setTimeout(r, 1500));

        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;
            
            // Toleransi warna (Menghapus warna putih/terang)
            for (let i = 0; i < data.length; i += 4) {
                const r = data[i]; const g = data[i+1]; const b = data[i+2];
                if (r > 230 && g > 230 && b > 230) {
                    data[i+3] = 0; // Jadikan Transparan
                }
            }
            ctx.putImageData(imageData, 0, 0);
            setBgImage(canvas.toDataURL('image/png'));
            setIsProcessing(false);
            if (showToast) showToast("Background berhasil dihapus! (Mode Client-side)", "success");
        };
        img.src = bgImage;
    };

    // Magic Eraser Logic
    const handleMagicErase = async () => {
        setIsProcessing(true);
        if (showToast) showToast("Memproses AI Inpainting...", "info");
        
        // Simulasi delay API Call
        await new Promise(r => setTimeout(r, 2000));

        // Bersihkan maskingan (Karena API Inpainting belum terpasang di backend)
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        
        setHasMask(false);
        setIsProcessing(false);
        
        if (showToast) showToast("Fitur Inpainting sesungguhnya membutuhkan integrasi endpoint API di backend Anda. UI/UX siap digunakan.", "info");
    };

    return (
        <div className="fixed inset-0 z-[120] bg-zinc-950 flex animate-in fade-in">
            {/* Sidebar Tools */}
            <div className="w-[280px] border-r border-zinc-800 bg-zinc-900/50 flex flex-col shrink-0 relative z-20">
                <div className="px-5 pt-10 pb-5 border-b border-zinc-800 flex items-center justify-between">
                    <h2 className="text-white font-bold flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-pink-500" /> Studio V2
                    </h2>
                    <button onClick={onClose} className="p-1.5 text-zinc-400 hover:text-white bg-zinc-800 hover:bg-zinc-700 rounded-lg transition-colors">
                        <X className="w-4 h-4" />
                    </button>
                </div>

                <div className="p-5 overflow-y-auto flex-1 flex flex-col gap-6">
                    {/* Tool Selection */}
                    <div className="space-y-3">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">Mode Kursor</label>
                        <div className="grid grid-cols-2 gap-2">
                            <button 
                                onClick={() => setStudioMode('move')}
                                className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all ${studioMode === 'move' ? 'bg-indigo-500/20 border-indigo-500/50 text-indigo-400' : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700/80 hover:text-zinc-200'}`}
                            >
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M3 3l7.07 16.97 2.51-7.39 7.39-2.51L3 3z" /></svg>
                                <span className="text-[11px] font-bold">Standard</span>
                            </button>
                            <button 
                                onClick={() => setStudioMode('erase')}
                                className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all ${studioMode === 'erase' ? 'bg-pink-500/20 border-pink-500/50 text-pink-400' : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700/80 hover:text-zinc-200'}`}
                            >
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                <span className="text-[11px] font-bold">Eraser</span>
                            </button>
                        </div>
                    </div>

                    {/* AI Actions */}
                    <div className="space-y-3 pt-4 border-t border-zinc-800">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">AI Actions</label>
                        
                        <button 
                            onClick={handleRemoveBG}
                            disabled={isProcessing}
                            className="w-full flex items-center justify-between p-3.5 rounded-xl bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 hover:border-zinc-500 text-zinc-200 transition-all disabled:opacity-50"
                        >
                            <div className="flex items-center gap-3">
                                <div className="p-1.5 bg-cyan-500/20 text-cyan-400 rounded-lg">
                                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                </div>
                                <div className="text-left">
                                    <p className="text-xs font-bold">Remove Background</p>
                                    <p className="text-[10px] text-zinc-500">Hapus area putih/solid</p>
                                </div>
                            </div>
                        </button>
                        
                        {studioMode === 'erase' && (
                            <div className="animate-in fade-in slide-in-from-top-2 p-4 bg-pink-500/10 border border-pink-500/20 rounded-xl space-y-4">
                                <div>
                                    <label className="text-xs font-bold text-pink-400 flex justify-between mb-2">
                                        Ukuran Brush <span>{brushSize}px</span>
                                    </label>
                                    <input 
                                        type="range" min="10" max="150" value={brushSize} 
                                        onChange={(e) => setBrushSize(e.target.value)} 
                                        className="w-full accent-pink-500"
                                    />
                                </div>
                                <button 
                                    onClick={handleMagicErase}
                                    disabled={!hasMask || isProcessing}
                                    className={`w-full py-2.5 rounded-lg text-xs font-bold transition-all shadow-lg ${hasMask && !isProcessing ? 'bg-pink-500 hover:bg-pink-600 text-white' : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'}`}
                                >
                                    {isProcessing ? 'Processing...' : 'Apply Magic Eraser'}
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Workspace Area */}
            <div className={`flex-1 flex items-center justify-center bg-zinc-950 overflow-hidden relative checkerboard-bg`}>
                
                {/* CSS untuk pattern transparan (Checkerboard) */}
                <style>{`
                    .checkerboard-bg {
                        background-image: linear-gradient(45deg, #18181b 25%, transparent 25%), linear-gradient(-45deg, #18181b 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #18181b 75%), linear-gradient(-45deg, transparent 75%, #18181b 75%);
                        background-size: 20px 20px;
                        background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
                    }
                `}</style>

                {isProcessing && (
                    <div className="absolute inset-0 z-50 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center">
                        <Loader2 className="w-10 h-10 text-pink-500 animate-spin mb-4" />
                        <p className="text-white font-bold tracking-widest animate-pulse">PROCESSING AI...</p>
                    </div>
                )}

                {/* Canvas Container */}
                <div className="relative inline-block border border-zinc-800 shadow-2xl rounded-xl overflow-hidden">
                    <img 
                        src={bgImage} 
                        className="max-w-[70vw] max-h-[85vh] object-contain block pointer-events-none" 
                        alt="Workspace" 
                    />
                    
                    {/* Drawing Mask Layer */}
                    <canvas
                        ref={canvasRef}
                        onPointerDown={startDrawing}
                        onPointerMove={draw}
                        onPointerUp={stopDrawing}
                        onPointerLeave={stopDrawing}
                        className={`absolute top-0 left-0 w-full h-full z-10 touch-none ${studioMode === 'erase' ? 'cursor-crosshair' : 'pointer-events-none'}`}
                    />
                </div>
            </div>
        </div>
    );
};

// --- SEAMLESS PATTERN CHECKER COMPONENT ---
const PatternChecker = ({ task, baseImageBase64, onClose }) => {
    const [scale, setScale] = useState(30); // Default 30% scale to clearly see the tiling

    return (
        <div className="fixed inset-0 z-[120] bg-zinc-950 flex flex-col animate-in fade-in">
            {/* Header Toolbar */}
            <div className="h-20 pt-6 pb-2 border-b border-zinc-800 bg-zinc-900/50 flex items-center justify-between px-6 shrink-0">
                <div className="flex items-center gap-4">
                    <h2 className="text-white font-bold flex items-center gap-2">
                        <LayoutGrid className="w-5 h-5 text-teal-500" /> Seamless Pattern Checker
                    </h2>
                    <div className="h-6 w-px bg-zinc-700 mx-2"></div>
                    <div className="flex items-center gap-3 text-sm text-zinc-300 font-medium bg-zinc-800/50 px-4 py-1.5 rounded-lg border border-zinc-700">
                        <span>Scale: {scale}%</span>
                        <input 
                            type="range" 
                            min="5" 
                            max="100" 
                            value={scale} 
                            onChange={(e) => setScale(e.target.value)} 
                            className="w-32 accent-teal-500 cursor-pointer"
                        />
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={onClose} className="p-2 text-zinc-400 hover:text-white bg-zinc-800 hover:bg-zinc-700 rounded-full transition-colors shadow-lg">
                        <X className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Workspace Area - Tiling Viewer */}
            <div className="flex-1 w-full bg-zinc-950 overflow-hidden relative shadow-inner">
                <div 
                    className="absolute inset-0"
                    style={{
                        backgroundImage: `url(${baseImageBase64})`,
                        backgroundRepeat: 'repeat',
                        backgroundSize: `${scale}%`,
                        backgroundPosition: 'center'
                    }}
                />
            </div>
        </div>
    );
};

// --- JEMBATAN KOMUNIKASI KE HTML PARENT (ANTI-CURI API KEY) ---
const callGeminiGateway = (endpointPath, payload) => {
    return new Promise((resolve, reject) => {
        // Buat ID unik untuk melacak pesan ini
        const messageId = 'msg_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
        
        const messageListener = (event) => {
            const data = event.data;
            // Jika balasan sesuai dengan ID yang kita kirim
            if (data && data.type === 'GEMINI_RESPONSE' && data.id === messageId) {
                window.removeEventListener('message', messageListener); // Bersihkan listener
                if (data.success) {
                    resolve(data.data);
                } else {
                    reject(new Error(data.error));
                }
            }
        };
        
        // Pasang telinga untuk mendengar balasan dari HTML
        window.addEventListener('message', messageListener);
        
        // Teriak (kirim data) ke HTML Parent
        window.parent.postMessage({
            type: 'CALL_GEMINI',
            id: messageId,
            endpointPath: endpointPath,
            payload: payload
        }, '*');
    });
};

// --- IMAGE ANALYSIS HELPER FOR REPLICA MODE & POV ---
const analyzeImageBase64 = async (base64Image, subjectBase64Image = null, customPrompt = null) => {
    const parts = [];
    
    if (base64Image && subjectBase64Image) {
        // FIX: Logika 2 Gambar (Replica Swap / Brand Kit Custom Mockup)
        // Sebelumnya Custom Prompt ditimpa jika ada 2 gambar. Sekarang diperbaiki.
        const resized1 = await resizeImageBase64(base64Image, 800);
        const mime1 = resized1.split(';')[0].split(':')[1];
        const data1 = resized1.split(',')[1];
        
        const resized2 = await resizeImageBase64(subjectBase64Image, 800);
        const mime2 = resized2.split(';')[0].split(':')[1];
        const data2 = resized2.split(',')[1];

        parts.push({ text: "Image 1 (Reference Scene/Style):" });
        parts.push({ inlineData: { mimeType: mime1 || "image/jpeg", data: data1 } });
        parts.push({ text: "Image 2 (New Target Subject/Logo):" });
        parts.push({ inlineData: { mimeType: mime2 || "image/jpeg", data: data2 } });
        
        const defaultPrompt = "Analyze these two images. Create a highly detailed prompt (MAX 100 WORDS) to generate a new image that EXACTLY replicates the background, lighting, composition, and visual style of Image 1, BUT completely replaces its main subject with the object shown in Image 2. Ensure the new subject fits seamlessly.";
        parts.push({ text: customPrompt ? customPrompt : defaultPrompt });

    } else if (base64Image) {
        // Logika 1 Gambar (Describe, Extract, dsb)
        const resized = await resizeImageBase64(base64Image, 800);
        const mimeType = resized.split(';')[0].split(':')[1];
        const base64Data = resized.split(',')[1];
        
        if (customPrompt) {
            parts.push({ text: customPrompt });
        } else {
            parts.push({ text: "Analyze this image. Read and transcribe any text/typography exactly. Describe the main subject, shapes, layout, colors, lighting, and artistic style. Output a single comprehensive descriptive prompt (MAX 100 WORDS) to recreate this image perfectly." });
        }
        parts.push({ inlineData: { mimeType: mimeType || "image/jpeg", data: base64Data } });

    } else if (subjectBase64Image) {
        // FIX: Logika Khusus jika HANYA Target Objek yang diunggah
        const resized = await resizeImageBase64(subjectBase64Image, 800);
        const mimeType = resized.split(';')[0].split(':')[1];
        const base64Data = resized.split(',')[1];
        
        if (customPrompt) {
             parts.push({ text: customPrompt });
        } else {
             parts.push({ text: "Analyze this object. Provide a brief but highly accurate visual description (MAX 50 WORDS) so it can be seamlessly incorporated into a new poster design as the main subject." });
        }
        parts.push({ inlineData: { mimeType: mimeType || "image/jpeg", data: base64Data } });
    } else {
        return "";
    }

    // Panggil lewat HTML Gateway (API Key aman di HTML)
    const data = await callGeminiGateway('gemini-2.5-flash-preview-09-2025:generateContent', {
        contents: [{
            role: "user",
            parts: parts
        }]
    });
    if (data.error) throw new Error(data.error.message);
    return data.candidates?.[0]?.content?.parts?.[0]?.text || "";
};

