const getRandomCategoryStr = (tab) => {
    const cats = Object.keys(menuCategories[tab]).filter(k => k !== 'CONTROL');
    const randomCat = cats[Math.floor(Math.random() * cats.length)];
    const subs = menuCategories[tab][randomCat];
    if (subs && subs.length > 0) {
        const randomSub = subs[Math.floor(Math.random() * subs.length)];
        return `${randomCat}, ${randomSub}`;
    }
    return randomCat;
};

const getRandomStyleStr = (tab) => {
    const styleCats = Object.keys(menuStyles[tab]).filter(k => k !== 'CONTROL');
    if (styleCats.length === 0) return 'None';
    const randomCat = styleCats[Math.floor(Math.random() * styleCats.length)];
    const subs = menuStyles[tab][randomCat];
    if (subs && subs.length > 0) {
        return subs[Math.floor(Math.random() * subs.length)];
    }
    return 'None';
};

