  // MENU SCROLL & DRAG STATE
  const menuContainerRef = useRef(null);
  const [isDraggingMenu, setIsDraggingMenu] = useState(false);
  const [startXMenu, setStartXMenu] = useState(0);
  const [scrollLeftMenu, setScrollLeftMenu] = useState(0);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);
  const [dragDistance, setDragDistance] = useState(0);

  const handleCloseSplash = () => {
      setShowSplash(false);
      localStorage.setItem('imagoz_splash_seen', 'true');
  };

  const checkScroll = () => {
      if (menuContainerRef.current) {
          const { scrollLeft, scrollWidth, clientWidth } = menuContainerRef.current;
          setCanScrollLeft(scrollLeft > 0);
          setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 2);
      }
  };

  useEffect(() => {
      checkScroll();
      window.addEventListener('resize', checkScroll);
      setTimeout(checkScroll, 100);
      return () => window.removeEventListener('resize', checkScroll);
  }, [activeTab]);

  const scrollMenu = (dir) => {
      if (menuContainerRef.current) {
          const amount = 300;
          menuContainerRef.current.scrollBy({ left: dir === 'left' ? -amount : amount, behavior: 'smooth' });
          setTimeout(checkScroll, 350);
      }
  };

  const handleMouseDownMenu = (e) => {
      setIsDraggingMenu(true);
      setDragDistance(0);
      setStartXMenu(e.pageX - menuContainerRef.current.offsetLeft);
      setScrollLeftMenu(menuContainerRef.current.scrollLeft);
  };

  const handleMouseLeaveMenu = () => {
      setIsDraggingMenu(false);
  };

  const handleMouseUpMenu = () => {
      setIsDraggingMenu(false);
  };

  const handleMouseMoveMenu = (e) => {
      if (!isDraggingMenu) return;
      e.preventDefault(); // Mencegah highlight text saat men-drag
      const x = e.pageX - menuContainerRef.current.offsetLeft;
      const walk = (x - startXMenu) * 1.5; // Kecepatan geser
      setDragDistance(Math.abs(x - startXMenu));
      menuContainerRef.current.scrollLeft = scrollLeftMenu - walk;
      checkScroll();
  };

  const [theme, setTheme] = useState(() => localStorage.getItem('imaginer_theme') || 'light');
  const isDark = theme === 'dark';

