  useEffect(() => { autoDeleteRef.current = autoDelete; localStorage.setItem('imaginer_autodel', JSON.stringify(autoDelete)); }, [autoDelete]);
  useEffect(() => { downloadFormatRef.current = downloadFormat; localStorage.setItem('imaginer_dl_format', downloadFormat); }, [downloadFormat]);
  useEffect(() => { localStorage.setItem('imaginer_theme', theme); }, [theme]);
  
  useEffect(() => { 
      const processHistory = async () => {
          // 1. Simpan gambar referensi yang besar (Base64) ke IndexedDB secara asinkron
          // FIX FATAL: Gunakan prev state callback untuk mencegah Race Condition yang menimpa status 'success' kembali ke 'processing'
          for (const task of history) {
              if (task.taskPayload) {
                  let hasChanges = false;
                  const newPayload = { ...task.taskPayload };
                  
                  for (const key of ['replicaPreview', 'replicaSubjectPreview', 'logoOriginalDataUrl', 'logoPreview', 'mergeImagePreviews']) {
                      // Khusus untuk array Base64 pada fitur MERGE
                      if (key === 'mergeImagePreviews' && Array.isArray(newPayload[key])) {
                          let arrayChanged = false;
                          const newArray = [...newPayload[key]];
                          for (let j = 0; j < newArray.length; j++) {
                              if (newArray[j] && newArray[j].startsWith('data:image')) {
                                  const id = `payload-${task.id}-merge-${j}`;
                                  await ImageStorage.save(id, newArray[j]);
                                  newArray[j] = `idb://${id}`;
                                  arrayChanged = true;
                                  hasChanges = true;
                              }
                          }
                          if (arrayChanged) newPayload[key] = newArray;
                      } 
                      // Untuk atribut tunggal biasa
                      else if (newPayload[key] && typeof newPayload[key] === 'string' && newPayload[key].startsWith('data:image')) {
                          const id = `payload-${task.id}-${key}`;
                          await ImageStorage.save(id, newPayload[key]);
                          newPayload[key] = `idb://${id}`;
                          hasChanges = true;
                      }
                  }
                  
                  if (hasChanges) {
                      setHistory(prev => prev.map(t => t.id === task.id ? { ...t, taskPayload: newPayload } : t));
                  }
              }
          }
          
          // 2. Simpan ke LocalStorage dengan aman (buang File/Blob object)
          try {
              const safeHistory = history.map(t => {
                  if (!t.taskPayload) return t;
                  const safePayload = { ...t.taskPayload };
                  Object.keys(safePayload).forEach(k => {
                      if (safePayload[k] instanceof File || safePayload[k] instanceof Blob) {
                          delete safePayload[k]; // Strip Blob/File objects
                      }
                  });
                  return { ...t, taskPayload: safePayload };
              });
              localStorage.setItem('imaginer_history', JSON.stringify(safeHistory)); 
          } catch(e) {
              console.error("Local storage save failed", e);
          }
      };
      
      processHistory();
  }, [history]);

  useEffect(() => { localStorage.setItem('imaginer_tokens', tokens.toString()); }, [tokens]);
  useEffect(() => { localStorage.setItem('imaginer_timers', JSON.stringify(tokenTimers)); }, [tokenTimers]);

  useEffect(() => { fetchModelsFromApi(); }, []);

  // AUTO-DELETE FAILED TASKS (5 MINUTES)
  useEffect(() => {
    const interval = setInterval(() => {
      setHistory(prev => {
        const now = Date.now();
        const filtered = prev.filter(t => {
          if (t.status === 'failed') {
            const failTime = t.failedAt || new Date(t.created_at).getTime();
            // Jika sudah lebih dari 5 menit (5 * 60 * 1000 ms), hapus
            if (now - failTime > 300000) {
              return false; 
            }
          }
          return true;
        });
        return filtered;
      });
    }, 60000); // Cek setiap 1 menit
    return () => clearInterval(interval);
  }, []);

  // HANDLE ACTIVE TASK IF DELETED
  useEffect(() => {
      if (activeTask && !history.some(t => t.id === activeTask)) {
          setActiveTask(history.length > 0 ? history[0].id : null);
      }
  }, [history, activeTask]);

  // TOKEN TIMER LOGIC (Core 1.0.16 restored)
  useEffect(() => {
    if (tokenTimers.length === 0) {
        setCooldownTime(0);
        return;
    }

    const interval = setInterval(() => {
        const now = Date.now();
        let updatedTimers = [];
        let tokensToRestore = 0;
        let nearestExpiry = Infinity;

            tokenTimers.forEach(timerObj => {
                if (now >= timerObj.expiresAt) {
                    tokensToRestore++;
                } else {
                    updatedTimers.push(timerObj);
                    if (timerObj.expiresAt < nearestExpiry) {
                       nearestExpiry = timerObj.expiresAt;
                    }
                }
            });

            if (tokensToRestore > 0) {
                setTokens(prev => Math.min(maxTokens, prev + tokensToRestore));
                setTokenTimers(updatedTimers);
            } else if (nearestExpiry !== Infinity && tokens === 0) {
                setCooldownTime(Math.ceil((nearestExpiry - now) / 1000));
            }

        }, 1000);

        return () => clearInterval(interval);
  }, [tokenTimers, tokens, maxTokens]);


  // NAVIGATION KEYBOARD HOTKEYS FOR THE CAROUSEL
  useEffect(() => {
    const handleKeyDown = (e) => {
        if (lightboxId) return; // Prevent carousel navigation when lightbox is open

        if (!activeTask || history.length === 0) return;
        const activeIdx = history.findIndex(t => t.id === activeTask);
        if (activeIdx === -1) return;

        if (e.key === 'ArrowLeft') {
            // Newer task is index - 1 (Looping ke akhir jika di awal)
            const prevIdx = activeIdx > 0 ? activeIdx - 1 : history.length - 1;
            setActiveTask(history[prevIdx].id);
        } else if (e.key === 'ArrowRight') {
            // Older task is index + 1 (Looping ke awal jika di akhir)
            const nextIdx = activeIdx < history.length - 1 ? activeIdx + 1 : 0;
            setActiveTask(history[nextIdx].id);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeTask, history, lightboxId]);

