  // Helper Upload (Konversi file langsung ke Base64 untuk menghindari masalah CORS/Blob yang kedaluwarsa)
  const handleFileUpload = (e, fileKey, previewKey, callback = null) => {
      const file = e.target.files[0];
      if (file) {
          updateTabData(fileKey, file);
          const reader = new FileReader();
          reader.onload = (event) => {
              const base64 = event.target.result;
              updateTabData(previewKey, base64);
              if (callback) callback(base64);
          };
          reader.readAsDataURL(file);
      }
      e.target.value = ''; // Reset input agar file yang sama bisa dipilih lagi
  };

  // Helper Upload untuk MERGE (Multi Image)
  const handleFileUploadMerge = (e) => {
      const files = Array.from(e.target.files);
      if (!files.length) return;
      
      const currentImages = tabData[activeTab].mergeImages || [];
      if (currentImages.length + files.length > 5) {
          return toast("Maksimal 5 gambar diperbolehkan!", "error");
      }

      files.forEach(file => {
          const reader = new FileReader();
          reader.onload = (event) => {
              setTabData(prev => ({
                  ...prev,
                  MERGE: {
                      ...prev.MERGE,
                      mergeImages: [...(prev.MERGE.mergeImages || []), event.target.result]
                  }
              }));
          };
          reader.readAsDataURL(file);
      });
      e.target.value = '';
  };

  const removeMergeImage = (index) => {
      setTabData(prev => {
          const newImages = [...(prev.MERGE.mergeImages || [])];
          newImages.splice(index, 1);
          
          let newPrimary = prev.MERGE.mergePrimaryIndex;
          if (newPrimary === index) newPrimary = null;
          else if (newPrimary > index) newPrimary -= 1;
          
          return { ...prev, MERGE: { ...prev.MERGE, mergeImages: newImages, mergePrimaryIndex: newPrimary } };
      });
  };

  const setPrimaryMergeImage = (index) => {
      setTabData(prev => ({
          ...prev,
          MERGE: {
              ...prev.MERGE,
              mergePrimaryIndex: prev.MERGE.mergePrimaryIndex === index ? null : index
          }
      }));
  };

  const handleAutoDescribeMerge = async () => {
      const images = formData.mergeImages || [];
      if (images.length < 2) return toast("Unggah minimal 2 gambar terlebih dahulu!", "error");
      
      setIsCampaignDescribing(true);
      try {
          
          // --- NEW LOGIC: STRUCTURED ANALYSIS PROMPT ---
          const systemPrompt = `You are a creative prompt engineer. Analyze the provided images. 
First, strictly identify and describe the primary subject or element in EACH image separately (e.g., Image 1: A fluffy Persian cat, Image 2: An astronaut suit).
Second, based on those identified elements, write a highly detailed, creative, and cohesive prompt in INDONESIAN describing how to perfectly merge them into a single stunning image.

Format your response EXACTLY like this example:
Image 1: [description]
Image 2: [description]

Generated Prompt:
"[Your creative Indonesian prompt here]..."`;
          
          const parts = [{ text: "Analyze these images and follow the exact formatting rules to create a merged prompt:" }];
          
          for (let i = 0; i < images.length; i++) {
              const resized = await resizeImageBase64(images[i], 800);
              const mimeType = resized.split(';')[0].split(':')[1];
              const base64Data = resized.split(',')[1];
              parts.push({ inlineData: { mimeType: mimeType || "image/jpeg", data: base64Data } });
          }

          const data = await callGeminiGateway('gemini-2.5-flash-preview-09-2025:generateContent', {
              contents: [{ parts: parts }],
              systemInstruction: { parts: [{ text: systemPrompt }] }
          });
          let analysisResult = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
          
          // Jika perlu dibersihkan sedikit (opsional)
          analysisResult = analysisResult.replace(/\*\*/g, '').trim();
          
          updateTabData('prompt', analysisResult);
          toast("Analisis gambar berhasil! Silakan edit prompt jika diperlukan.", "success");
      } catch (e) {
          console.error(e);
          toast("Gagal merangkum instruksi penggabungan.", "error");
      } finally {
          setIsCampaignDescribing(false);
      }
  };

  // Enable Paste for REPLICA, POSTER & POV tabs
  useEffect(() => {
    const handlePaste = (e) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          const reader = new FileReader();
          reader.onload = (event) => {
             if (activeTab === 'POSTER') {
                 updateTabData('posterLayoutFile', blob);
                 updateTabData('posterLayoutPreview', event.target.result);
             } else if (activeTab === 'POV') {
                 updateTabData('povProductFile', blob);
                 updateTabData('povProductPreview', event.target.result);
             } else if (activeTab === 'REPLICA') {
                 updateTabData('replicaLayoutFile', blob);
                 updateTabData('replicaLayoutPreview', event.target.result);
             } else if (activeTab === 'CAMPAIGN') {
                 updateTabData('campaignProductFile', blob);
                 updateTabData('campaignProductPreview', event.target.result);
                 handleAutoDescribeCampaign(event.target.result); // Auto Describe when pasted
             } else if (activeTab === 'BRAND_KIT') {
                 updateTabData('logoFile', blob);
                 updateTabData('logoPreview', event.target.result);
                 handleAnalyzeBrandLogo(event.target.result); // Auto Extract when pasted
             } else if (activeTab === 'ADS_KIT') {
                 updateTabData('adsKitProductFile', blob);
                 updateTabData('adsKitProductPreview', event.target.result);
                 handleAutoDescribeAdsKit(event.target.result); // Auto Describe when pasted
             } else if (activeTab === 'PRODUCT') {
                 updateTabData('productFile', blob);
                 updateTabData('productPreview', event.target.result);
                 handleAutoDescribeProduct(event.target.result); // Auto Describe when pasted
             } else if (activeTab === 'MOCKUP') {
                 updateTabData('mockupLogoFile', blob);
                 updateTabData('mockupLogoPreview', event.target.result);
             } else if (activeTab === 'TEXT_EFFECT') {
                 // Izinkan paste background khusus untuk Text Effect jika opsi Upload terpilih
                 if (formData.textVibe === 'upload') {
                     updateTabData('textBgFile', blob);
                     updateTabData('textBgPreview', event.target.result);
                 }
                 return;
             } else {
                 updateTabData('refFile', blob);
                 updateTabData('refPreview', event.target.result);
             }
          };
          reader.readAsDataURL(blob);
          break; // Hanya ambil 1 gambar pertama dari clipboard
        }
      }
    };
    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [activeTab, tabData]);

