  // QUEUE WORKER LOGIC (Core 1.0.16 restored & Upgraded to Parallel Workers)
  useEffect(() => {
    if (!isBatchProcessing || batchQueue.length === 0) {
        if (isBatchProcessing && batchQueue.length === 0) {
            setIsBatchProcessing(false);
            setIsQueuePaused(false);
            toast("Semua antrean batch selesai!", "success");
        }
        return;
    }

    if (isQueuePaused) return;

    const activeWorkersCount = history.filter(t => ['sending', 'processing', 'polling', 'retrying'].includes(t.status)).length;
    const allowedWorkers = tier === 'PAID' ? 5 : 3; // Eksekusi 5 gambar sekaligus di PAID mode!

    if (tier === 'PAID' && tokens === 0) return; 

    if (activeWorkersCount < allowedWorkers && (tier === 'FREE' || tokens > 0)) {
        const nextQueueItem = batchQueue[0];
        // Pop dari antrean langsung (tanpa timeout) agar worker bisa menembak beruntun
        setBatchQueue(prev => prev.slice(1));
        
        if (nextQueueItem.tier === 'FREE') {
            executeGenerateFreeTask(nextQueueItem);
        } else {
            executeGenerateQueueItem(nextQueueItem);
        }
    }
  }, [isBatchProcessing, batchQueue, history, tokens, tier]);

