        setActiveTask(newTasks[0].id);
        setBatchQueue(prev => [...prev, ...newQueueItems]);
        setIsBatchProcessing(true);
        toast(`Memulai antrean Food Studio: ${newQueueItems.length} task...`, "info");
        return;
