  // sudah ada isinya. Ini bikin Stacked View sempat kosong (activeIdx = -1) sampai user
  // generate gambar baru. Di sini kita sinkronkan activeTask ke item pertama otomatis
  // kalau belum ada yang dipilih, supaya gambar lama langsung tampil di Stacked View.
  useEffect(() => {
      if (!activeTask && history.length > 0) {
          setActiveTask(history[0].id);
      }
  }, [activeTask, history]);
  const isGenerating = history.some(t => ['sending', 'processing', 'polling'].includes(t.status));
  
  // Use correct model list for finding current model details
  const activeModelsList = tier === 'FREE' ? freeModels : models;
  const currentModelData = activeModelsList.find(m => m.id === formData?.model) || activeModelsList[0]; // FIX: Ditambahkan fallback agar UI tidak pernah hilang
  
  const successCount = history.filter(t => t.status === 'success').length;

  const getLightboxData = () => history.find(t => t.id === lightboxId);
  const lbData = getLightboxData();

  const handleOpenStudio = async (targetTask) => {
      const taskToEdit = targetTask && targetTask.urls ? targetTask : lbData;
      if (!taskToEdit || !taskToEdit.urls || !taskToEdit.urls[0]) return;
      
      const isPattern = taskToEdit.tabMode === 'PATTERN';
      
      setIsPreparingStudio(true);
      toast(isPattern ? "Menyiapkan Pattern Checker..." : "Menyiapkan Poster Studio...", "info");
      
      try {
          const url = taskToEdit.urls[0];
          let base64Img = url;
          
          if (url.startsWith('idb://')) {
              const id = url.replace('idb://', '');
              base64Img = await ImageStorage.get(id);
              if (!base64Img) {
                  setIsPreparingStudio(false);
                  return toast("Gagal memuat gambar dari penyimpanan lokal.", "error");
              }
          }
          
          // Jika url biasa (dari server), konversi ke base64 menggunakan proxy untuk menghindari limit CORS
          if (base64Img && !base64Img.startsWith('data:image')) {
              try {
                  const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(base64Img)}`;
                  const res = await fetch(proxyUrl);
                  if (!res.ok) throw new Error("Proxy fetch failed");
                  const blob = await res.blob();
                  base64Img = await new Promise((resolve) => {
                      const reader = new FileReader();
                      reader.onloadend = () => resolve(reader.result);
                      reader.readAsDataURL(blob);
                  });
              } catch (e) {
                  setIsPreparingStudio(false);
                  return toast("Gagal mengkonversi gambar (Terblokir CORS).", "error");
              }
          }
          
          if (isPattern) {
              setPatternCheckData({ task: taskToEdit, base64: base64Img });
          } else {
              setStudioData({ task: taskToEdit, base64: base64Img });
          }
          setLightboxId(null); // Tutup lightbox jika terbuka
      } catch (err) {
          console.error("Advanced Action Error:", err);
          toast("Terjadi kesalahan sistem.", "error");
      }
      setIsPreparingStudio(false);
  };

  useEffect(() => {
      if (lbData && lbData.urls && lbData.urls[0]) {
          const url = lbData.urls[0];

          if (url.startsWith('idb://')) {
              const id = url.replace('idb://', '');
              ImageStorage.get(id).then(base64 => {
                  if (base64) {
                      const base64Length = base64.length - (base64.indexOf(',') + 1);
                      const padding = (base64.charAt(base64.length - 2) === '=') ? 2 : ((base64.charAt(base64.length - 1) === '=') ? 1 : 0);
                      const fileSize = (base64Length * 0.75) - padding;
                      setLightboxFileSize((fileSize / (1024 * 1024)).toFixed(2) + ' MB');
                  } else {
                      setLightboxFileSize('Unknown');
                  }
              });
              return;
          }

          if (url.startsWith('data:image')) {
              const base64Length = url.length - (url.indexOf(',') + 1);
              const padding = (url.charAt(url.length - 2) === '=') ? 2 : ((url.charAt(url.length - 1) === '=') ? 1 : 0);
              const fileSize = (base64Length * 0.75) - padding;
              setLightboxFileSize((fileSize / (1024 * 1024)).toFixed(2) + ' MB');
              return;
          }

          setLightboxFileSize('Calculating...');
          fetch(url, { method: 'HEAD' })
            .then(res => {
                const size = res.headers.get('content-length');
                if (size) setLightboxFileSize((size / (1024 * 1024)).toFixed(2) + ' MB');
                else setLightboxFileSize('Unknown');
            })
            .catch(() => setLightboxFileSize('Unknown'));
      }
  }, [lbData]);

  const navLightbox = (dir) => {
      const successTasks = history.filter(t => t.status === 'success' && t.urls?.[0]);
      if (successTasks.length === 0) return;
      const idx = successTasks.findIndex(t => t.id === lightboxId);
      if (idx === -1) return;
      let newIdx = idx + dir;
      if (newIdx < 0) newIdx = successTasks.length - 1;
      if (newIdx >= successTasks.length) newIdx = 0;
      setSlideDir(dir > 0 ? 'right' : 'left'); // Animasi arah lightbox
      setLightboxId(successTasks[newIdx].id);
  };

  // LIGHTBOX KEYBOARD NAVIGATION
  useEffect(() => {
      if (!lightboxId) return;
      const handleKeyDown = (e) => {
          if (e.key === 'ArrowLeft') navLightbox(-1);
          else if (e.key === 'ArrowRight') navLightbox(1);
          else if (e.key === 'Escape') setLightboxId(null);
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [lightboxId, history]);

